Why does `emp` end up as `None`?

```python
class Employee:
    def __init__(self, name):
        self.name = name

    @classmethod
    def from_string(cls, data):
        name = data.split(",")[0]
        cls(name)          # intended to return new instance

emp = Employee.from_string("Alice,Engineering")
print(emp)
```

What is missing in the `SavingAccount` constructor?

```python
class BankAccount:
    def __init__(self, balance):
        self.balance = balance

class SavingAccount(BankAccount):
    def __init__(self, balance, interest):
        self.interest = interest

acc = SavingAccount(1000, 0.03)
print(acc.balance)
```

What error does this code produce?

```python
class Account:
    def __init__(self, number):
        self.number = number

class CreditAccount(Account):
    def __init__(self, number, limit):
        self.limit = limit
    def show_number(self):
        return self.number

c = CreditAccount(123, 5000)
print(c.show_number())
```

What will be the balance after this code runs?

```python
class BankAccount:
    def __init__(self, balance):
        self.balance = balance
    def withdraw(self, amount):
        self.balance -= amount

class SavingsAccount(BankAccount):
    def withdraw(self, amount):
        print("Logging withdrawal")
        # forgot to call parent's withdraw

acc = SavingsAccount(500)
acc.withdraw(100)
print(acc.balance)
```

What is the problem with this `__eq__` implementation?

```python
class Product:
    def __init__(self, code):
        self.code = code
    def __eq__(self, other):
        return (self.code = other.code)
```

What can go wrong with this equality check?

```python
class Book:
    def __init__(self, isbn):
        self.isbn = isbn
    def __eq__(self, other):
        return self.isbn == other.isbn

class Magazine:
    def __init__(self, isbn):
        self.isbn = isbn

b = Book("123")
m = Magazine("123")
print(b == m)   # Returns True, but they are different types.
```

What error occurs when calling `process(chk)`?

```python
class BankAccount:
    def withdraw(self, amount):
        self.balance -= amount

class CheckingAccount(BankAccount):
    def withdraw(self, amount, fee):
        if amount + fee <= self.limit:
            BankAccount.withdraw(self, amount + fee)

def process(acct):
    acct.withdraw(50)

chk = CheckingAccount()
chk.balance = 200
chk.limit = 100
process(chk)
```

